card('h5-c6','hist5-l3',X('Open source vs. no-cost','Código abierto frente a gratuito','Código aberto versus sem custo'),X('Different ideas: open source is about license rights; price may vary.','Ideas distintas: código abierto trata de derechos; el precio puede variar.','Ideias distintas: código aberto trata de direitos; o preço pode variar.'),'distinction'),
card('h5-c7','hist5-l3',X('When was the Linux kernel released?','¿Cuándo se publicó el kernel Linux?','Quando o kernel Linux foi lançado?'),X('1991.','1991.','1991.')),
card('h5-c8','hist5-l4',X('What does outsourcing change?','¿Qué cambia la externalización?','O que a terceirização muda?'),X('Who performs work and how it is coordinated; product accountability remains.','Quién realiza el trabajo y cómo se coordina; se mantiene la responsabilidad.','Quem realiza o trabalho e como ele é coordenado; a responsabilidade permanece.')),
card('h5-c9','hist5-l4',X('Name a distributed-team risk.','Nombra un riesgo de equipo distribuido.','Cite um risco de equipe distribuída.'),X('Lost context, unclear ownership, weak security controls, or poor knowledge transfer.','Pérdida de contexto, responsabilidad ambigua, controles débiles o transferencia deficiente.','Perda de contexto, responsabilidade ambígua, controles fracos ou transferência inadequada.')),
card('h5-c10','hist5-l5',X('What is SaaS?','¿Qué es SaaS?','O que é SaaS?'),X('An application operated by a provider and made available as a service, often through a browser.','Aplicación operada por proveedor y ofrecida como servicio, a menudo en navegador.','Aplicação operada por provedor e oferecida como serviço, muitas vezes pelo navegador.')),
card('h5-c11','hist5-l5',X('Name a cloud tradeoff.','Nombra una compensación de la nube.','Cite uma compensação da nuvem.'),X('Convenient provisioning and updates versus recurring cost, provider dependence, and portability concerns.','Agilidad y actualizaciones frente a costos recurrentes, dependencia y portabilidad.','Provisionamento e atualizações versus custos recorrentes, dependência e portabilidade.')),
card('h5-c12','hist5-l2',X('Why did personal computers matter to software markets?','¿Por qué importaron las computadoras personales?','Por que computadores pessoais importaram?'),X('They expanded the potential user base and demand for applications.','Ampliaron los usuarios potenciales y la demanda de aplicaciones.','Ampliaram usuários potenciais e demanda por aplicações.'))
