const questions:Question[]=[
mc('h5-q1','hist5-l1',X('What did unbundling make more visible?','¿Qué hizo más visible la separación?','O que o unbundling tornou mais visível?'),[X('Software could be priced separately from hardware.','El software podía cobrarse separado del hardware.','Software podia ser cobrado separadamente do hardware.'),X('Software no longer needed users.','El software ya no necesitaba usuarios.','Software não precisava mais de usuários.'),X('All programs became public domain.','Todos los programas pasaron al dominio público.','Todos os programas passaram ao domínio público.'),X('Hardware became unnecessary.','El hardware se volvió innecesario.','Hardware tornou-se desnecessário.')],0,X('Separate pricing helped clarify software as a distinct product or service.','El precio separado hizo visible el software como producto o servicio propio.','Preço separado tornou software visível como produto ou serviço próprio.')),
tf('h5-q2','hist5-l1',X('IBM’s 1969 pricing change alone created the entire software industry.','El cambio de precios de IBM en 1969 creó por sí solo toda la industria.','A mudança de preços da IBM em 1969 criou sozinha toda a indústria.'),false,X('Industry growth involved many firms, users, products, and distribution changes.','El crecimiento involucró empresas, usuarios, productos y distribución diversos.','O crescimento envolveu empresas, usuários, produtos e distribuição diversos.')),
mc('h5-q3','hist5-l2',X('Why did packaged software scale commercially?','¿Por qué escaló comercialmente el software empaquetado?','Por que software empacotado escalou comercialmente?'),[X('A common product could be offered to many customers.','Un producto común podía ofrecerse a muchos clientes.','Um produto comum podia ser oferecido a muitos clientes.'),X('It never required updates.','Nunca necesitaba actualizaciones.','Nunca exigia atualizações.'),X('It was designed for only one user.','Se diseñaba para una sola persona.','Era projetado para uma única pessoa.'),X('It eliminated support.','Eliminó el soporte.','Eliminou suporte.')],0,X('A reusable product spreads development across a wider customer base.','Un producto reutilizable distribuye el desarrollo entre más clientes.','Um produto reutilizável distribui desenvolvimento por uma base maior de clientes.')),
fill('h5-q4','hist5-l3',X('Open-source licenses define rights to inspect, use, modify, or ______ source code.','Las licencias abiertas definen derechos de revisar, usar, modificar o ______ código.','Licenças abertas definem direitos de inspecionar, usar, modificar ou ______ código.'),['redistribute','redistribuir','redistribuir'],X('Redistribution rights are part of many open-source licenses.','La redistribución forma parte de muchas licencias abiertas.','Redistribuição faz parte de muitas licenças abertas.')),
matching('h5-q5','hist5-l3',X('Match the software approach with a characteristic.','Relaciona el enfoque con su característica.','Associe a abordagem à característica.'),[X('Open-source project','Proyecto de código abierto','Projeto de código aberto'),X('Proprietary product','Producto propietario','Produto proprietário'),X('Both','Ambos','Ambos')],[X('Rights defined by an open license','Derechos definidos por una licencia abierta','Direitos definidos por licença aberta'),X('Use controlled by owner’s license terms','Uso regido por licencia del propietario','Uso regido pelos termos do proprietário'),X('Need maintenance and security response','Requieren mantenimiento y respuesta de seguridad','Exigem manutenção e resposta de segurança')],[0,1,2],X('Licensing differs, but all software needs responsible stewardship.','Las licencias difieren, pero todo software necesita mantenimiento responsable.','Licenças diferem, mas todo software exige manutenção responsável.')),
tf('h5-q6','hist5-l4',X('Outsourcing removes the customer’s responsibility for product quality.','La externalización elimina la responsabilidad del cliente por la calidad.','Terceirização remove responsabilidade do cliente pela qualidade.'),false,X('The customer retains product ownership and must define acceptance and oversight.','El cliente conserva responsabilidad por producto, aceptación y supervisión.','O cliente mantém responsabilidade pelo produto, aceitação e supervisão.')),
mc('h5-q7','hist5-l4',X('What helps a distributed partnership work well?','¿Qué favorece una colaboración distribuida?','O que favorece uma parceria distribuída?'),[X('Clear ownership, deliverables, security, communication, and handover.','Responsabilidades, entregables, seguridad, comunicación y transferencia claras.','Responsabilidades, entregas, segurança, comunicação e transição claras.'),X('No shared documentation.','No compartir documentación.','Não compartilhar documentação.'),X('No acceptance criteria.','No tener criterios de aceptación.','Não ter critérios de aceitação.'),X('Use price as the only measure.','Usar solo el precio como medida.','Usar apenas preço como medida.')],0,X('Distributed work depends on explicit agreements and shared context.','El trabajo distribuido depende de acuerdos explícitos y contexto compartido.','Trabalho distribuído depende de acordos explícitos e contexto compartilhado.')),
fill('h5-q8','hist5-l5',X('Software as a Service is abbreviated ______.','Software como servicio se abrevia ______.','Software como Serviço é abreviado ______.'),['saas'],X('SaaS is the common abbreviation for Software as a Service.','SaaS es la abreviatura de Software as a Service.','SaaS é a sigla de Software as a Service.')),
mc('h5-q9','hist5-l5',X('What is a cloud adoption tradeoff to evaluate?','¿Qué compensación de nube se debe evaluar?','Que compensação da nuvem deve ser avaliada?'),[X('Provider dependence and exit options as well as convenience.','Dependencia y salida del proveedor, además de conveniencia.','Dependência e saída do provedor, além da conveniência.'),X('Cloud has no operating costs.','La nube no tiene costos operativos.','Nuvem não tem custos operacionais.'),X('Data cannot be lost.','Los datos no pueden perderse.','Dados não podem ser perdidos.'),X('Updates stop permanently.','Las actualizaciones cesan para siempre.','Atualizações param permanentemente.')],0,X('Convenience should be weighed against recurring cost, reliability, data, and portability.','La conveniencia se compara con costo recurrente, confiabilidad, datos y portabilidad.','Conveniência deve ser avaliada junto a custos recorrentes, confiabilidade, dados e portabilidade.')),
short('h5-q10','hist5-l2',X('Name one factor that expanded software demand with personal computers.','Nombra un factor que amplió la demanda con computadoras personales.','Cite um fator que ampliou demanda com computadores pessoais.'),['spreadsheet|hoja de calculo|planilha','home|hogar|casa','school|escuela|escola','small business|pequena empresa|small business','application|aplicacion|aplicação'],X('New users and practical applications increased demand for software products.','Nuevos usuarios y aplicaciones útiles aumentaron la demanda.','Novos usuários e aplicações úteis aumentaram a demanda.'))
];
